            'weapons.trait.dnd5e.twoHanded': 'Two-Handed',
            'weapons.trait.dnd5e.versatile': 'Versatile',
            'weapons.trait.dnd5e.ammunitionDesc': 'You can use a weapon that has the ammunition property to make a ranged attack only if you have ammunition to fire from the weapon. Each time you attack with the weapon, you expend one piece of ammunition. Drawing the ammunition from a quiver, case, or other container is part of the attack (you need a free hand to load a one-handed weapon). At the end of the battle, you can recover half your expended ammunition by taking a minute to search the battlefield. If you use a weapon that has the ammunition property to make a melee attack, you treat the weapon as an improvised weapon. A sling must be loaded to deal any damage when used in this way.',
            'weapons.trait.dnd5e.finesseDesc': 'When making an attack with a finesse weapon, you use your choice of your Strength or Dexterity modifier for the attack and damage rolls. You must use the same modifier for both rolls.',
            'weapons.trait.dnd5e.heavyDesc': 'Small creatures have disadvantage on attack rolls with heavy weapons. A heavy weapon\'s size and bulk make it too large for a Small creature to use effectively.',
            'weapons.trait.dnd5e.lightDesc': 'A light weapon is small and easy to handle, making it ideal for use when fighting with two weapons.',
            'weapons.trait.dnd5e.loadingDesc': 'Because of the time required to load this weapon, you can fire only one piece of ammunition from it when you use an action, bonus action, or reaction to fire it, regardless of the number of attacks you can normally make.',
            'weapons.trait.dnd5e.reachDesc': 'This weapon adds 5 feet to your reach when you attack with it, as well as when determining your reach for opportunity attacks with it.',
            'weapons.trait.dnd5e.specialDesc': 'A weapon with the special property has unusual rules governing its use, explained in the weapon\'s description.',
            'weapons.trait.dnd5e.thrownDesc': 'If a weapon has the thrown property, you can throw the weapon to make a ranged attack. If the weapon is a melee weapon, you use the same ability modifier for that attack roll and damage roll that you would use for a melee attack with the weapon. For example, if you throw a handaxe, you use your Strength, but if you throw a dagger, you can use either your Strength or your Dexterity, since the dagger has the finesse property.',
            'weapons.trait.dnd5e.twoHandedDesc': 'This weapon requires two hands when you attack with it.',
            'weapons.trait.dnd5e.versatileDesc': 'This weapon can be used with one or two hands. A damage value in parentheses appears with the property—the damage when the weapon is used with two hands to make a melee attack.',

            // PF2e traits
            'weapons.trait.pf2e.agile': 'Agile',
            'weapons.trait.pf2e.agileDesc': 'The multiple attack penalty you take with this weapon on the second attack is –4 instead of –5, and –8 instead of –10 on the third and subsequent attacks in the turn.',
            'weapons.trait.pf2e.deadly': 'Deadly',
            'weapons.trait.pf2e.deadlyDesc': 'On a critical hit, this weapon adds one extra die of the listed size to the damage. Enter the die size (e.g. d8).',
            'weapons.trait.pf2e.fatal': 'Fatal',
            'weapons.trait.pf2e.fatalDesc': 'On a critical hit, the weapon damage die changes to the listed die size and you add 1 extra die. Enter the die size (e.g. d12).',
            'weapons.trait.pf2e.finesse': 'Finesse',
            'weapons.trait.pf2e.finesseDesc': 'You can use your Dexterity modifier instead of your Strength modifier on attack rolls with this melee weapon.',
            'weapons.trait.pf2e.forceful': 'Forceful',
            'weapons.trait.pf2e.forcefulDesc': 'This weapon becomes more powerful with each attack you make against the same target. The second attack deals 1 extra damage, and each subsequent attack deals 2 extra damage.',
            'weapons.trait.pf2e.propulsive': 'Propulsive',
            'weapons.trait.pf2e.propulsiveDesc': 'You add half your Strength modifier (if positive) to damage rolls with this ranged weapon.',
            'weapons.trait.pf2e.reach': 'Reach',
