            'weapons.trait.dnd5e.thrown': 'Arrojadiza',
            'weapons.trait.dnd5e.twoHanded': 'A Dos Manos',
            'weapons.trait.dnd5e.versatile': 'Versátil',
            'weapons.trait.dnd5e.ammunitionDesc': 'Solo puedes usar un arma con la propiedad de munición para hacer un ataque a distancia si tienes munición para dispararla. Cada vez que atacas con el arma, gastas una pieza de munición. Sacar la munición de una aljaba, carcaj u otro contenedor forma parte del ataque (necesitas una mano libre para cargar un arma de una mano). Al final de la batalla, puedes recuperar la mitad de la munición gastada tomándote un minuto para buscar en el campo de batalla. Si usas un arma con la propiedad de munición para hacer un ataque cuerpo a cuerpo, tratas el arma como un arma improvisada. Una honda debe estar cargada para causar daño de esta manera.',
            'weapons.trait.dnd5e.finesseDesc': 'Al hacer un ataque con un arma de finura, puedes elegir usar tu modificador de Fuerza o Destreza para las tiradas de ataque y daño. Debes usar el mismo modificador para ambas tiradas.',
            'weapons.trait.dnd5e.heavyDesc': 'Las criaturas pequeñas tienen desventaja en las tiradas de ataque con armas pesadas. El tamaño y la masa de un arma pesada la hacen demasiado grande para que una criatura pequeña la use eficazmente.',
            'weapons.trait.dnd5e.lightDesc': 'Un arma ligera es pequeña y fácil de manejar, lo que la hace ideal para usarla cuando se combate con dos armas.',
            'weapons.trait.dnd5e.loadingDesc': 'Debido al tiempo necesario para cargar esta arma, solo puedes disparar una pieza de munición con ella cuando uses una acción, acción adicional o reacción para dispararla, independientemente del número de ataques que normalmente puedas hacer.',
            'weapons.trait.dnd5e.reachDesc': 'Esta arma añade 1,5 metros a tu alcance cuando atacas con ella, así como al determinar tu alcance para ataques de oportunidad.',
            'weapons.trait.dnd5e.specialDesc': 'Un arma con la propiedad especial tiene reglas inusuales que rigen su uso, explicadas en la descripción del arma.',
            'weapons.trait.dnd5e.thrownDesc': 'Si un arma tiene la propiedad de arrojadiza, puedes lanzar el arma para hacer un ataque a distancia. Si el arma es cuerpo a cuerpo, usas el mismo modificador de característica para esa tirada de ataque y daño que usarías para un ataque cuerpo a cuerpo. Por ejemplo, si lanzas un hacha de mano, usas Fuerza, pero si lanzas una daga, puedes usar Fuerza o Destreza, ya que la daga tiene la propiedad de finura.',
            'weapons.trait.dnd5e.twoHandedDesc': 'Esta arma requiere dos manos cuando atacas con ella.',
            'weapons.trait.dnd5e.versatileDesc': 'Esta arma se puede usar con una o dos manos. Un valor de daño entre paréntesis aparece con la propiedad: el daño cuando el arma se usa con dos manos para hacer un ataque cuerpo a cuerpo.',

            // PF2e traits
            'weapons.trait.pf2e.agile': 'Ágil',
            'weapons.trait.pf2e.agileDesc': 'La penalización por ataques múltiples que recibes con esta arma en el segundo ataque es –4 en lugar de –5, y –8 en lugar de –10 en el tercero y ataques posteriores en el turno.',
            'weapons.trait.pf2e.deadly': 'Mortífera',
            'weapons.trait.pf2e.deadlyDesc': 'En un golpe crítico, esta arma añade un dado extra del tamaño indicado al daño. Introduce el tamaño del dado (p.ej. d8).',
            'weapons.trait.pf2e.fatal': 'Fatal',
            'weapons.trait.pf2e.fatalDesc': 'En un golpe crítico, el dado de daño del arma cambia al tamaño de dado indicado y añades 1 dado extra. Introduce el tamaño del dado (p.ej. d12).',
            'weapons.trait.pf2e.finesse': 'Finura',
            'weapons.trait.pf2e.finesseDesc': 'Puedes usar tu modificador de Destreza en lugar de tu modificador de Fuerza en las tiradas de ataque con esta arma cuerpo a cuerpo.',
            'weapons.trait.pf2e.forceful': 'Poderosa',
            'weapons.trait.pf2e.forcefulDesc': 'Esta arma se vuelve más potente con cada ataque que realizas contra el mismo objetivo. El segundo ataque causa 1 daño extra, y cada ataque posterior causa 2 daños extra.',
            'weapons.trait.pf2e.propulsive': 'Propulsiva',
            'weapons.trait.pf2e.propulsiveDesc': 'Añades la mitad de tu modificador de Fuerza (si es positivo) a las tiradas de daño con esta arma a distancia.',
            'weapons.trait.pf2e.reach': 'Alcance',
            'weapons.trait.pf2e.reachDesc': 'Esta arma se puede usar para atacar criaturas a hasta 3 metros en lugar de solo criaturas adyacentes.',
            'weapons.trait.pf2e.sweep': 'Barrido',
            'weapons.trait.pf2e.sweepDesc': 'Esta arma realiza amplios movimientos de barrido, otorgando un bonificador de circunstancia +1 a tu tirada de ataque si ya intentaste atacar a un objetivo diferente este turno.',
            'weapons.trait.pf2e.thrown': 'Arrojadiza',
            'weapons.trait.pf2e.thrownDesc': 'Puedes lanzar esta arma como ataque a distancia. Introduce el incremento de alcance (p.ej. 6 m).',
            'weapons.trait.pf2e.twoHand': 'Dos Manos',
            'weapons.trait.pf2e.twoHandDesc': 'Esta arma se puede empuñar con dos manos para aumentar su daño. Introduce el tamaño de dado a dos manos (p.ej. d10).',
            'weapons.trait.pf2e.versatile': 'Versátil',
            'weapons.trait.pf2e.versatileDesc': 'Un arma versátil puede causar un tipo de daño diferente. Introduce el tipo de daño alternativo (p.ej. C, M o P).',

