            'cond.dnd5e.blinded': 'Geblendet',
            'cond.dnd5e.blindedDesc': 'Kann nicht sehen. Scheitert automatisch bei Proben, die Sicht erfordern. Nachteil bei Angriffswürfen; Angriffe gegen diese Kreatur haben Vorteil.',
            'cond.dnd5e.charmed': 'Bezaubert',
            'cond.dnd5e.charmedDesc': 'Kann den Bezauberer nicht angreifen. Der Bezauberer hat Vorteil bei sozialen Proben gegen diese Kreatur.',
            'cond.dnd5e.deafened': 'Taub',
            'cond.dnd5e.deafenedDesc': 'Kann nicht hören. Scheitert automatisch bei Proben, die Hören erfordern.',
            'cond.dnd5e.exhaustion': 'Erschöpfung',
            'cond.dnd5e.exhaustionDesc': 'Kumulative Erschöpfungsstufen mit zunehmend schweren Strafen. Stufe 6 bedeutet Tod.',
            'cond.dnd5e.frightened': 'Verängstigt',
            'cond.dnd5e.frightenedDesc': 'Nachteil bei Proben und Angriffen, solange die Angstquelle in Sichtlinie ist. Kann sich nicht willentlich nähern.',
            'cond.dnd5e.grappled': 'Gepackt',
            'cond.dnd5e.grappledDesc': 'Bewegung wird 0. Endet, wenn der Greifer handlungsunfähig wird oder die Kreatur außer Reichweite gerät.',
            'cond.dnd5e.incapacitated': 'Handlungsunfähig',
            'cond.dnd5e.incapacitatedDesc': 'Kann keine Aktionen oder Reaktionen ausführen.',
            'cond.dnd5e.invisible': 'Unsichtbar',
            'cond.dnd5e.invisibleDesc': 'Ohne Magie oder besondere Sinne nicht sichtbar. Angriffe haben Vorteil; Angriffe gegen haben Nachteil.',
            'cond.dnd5e.paralyzed': 'Gelähmt',
            'cond.dnd5e.paralyzedDesc': 'Handlungsunfähig; kann sich nicht bewegen oder sprechen. Scheitert automatisch bei St.- und Ges.-Rettungswürfen. Angriffe dagegen haben Vorteil; Nahkampftreffer sind kritisch.',
            'cond.dnd5e.petrified': 'Versteint',
            'cond.dnd5e.petrifiedDesc': 'In Stein verwandelt. Handlungsunfähig, bewusstlos. Resistenz gegen allen Schaden. Immun gegen Gift und Krankheit.',
            'cond.dnd5e.poisoned': 'Vergiftet',
            'cond.dnd5e.poisonedDesc': 'Nachteil bei Angriffswürfen und Proben.',
            'cond.dnd5e.prone': 'Liegend',
            'cond.dnd5e.proneDesc': 'Kann nur kriechen. Nachteil bei Angriffen. Nahkampfangriffe dagegen haben Vorteil; Fernkampfangriffe haben Nachteil.',
            'cond.dnd5e.restrained': 'Festgehalten',
            'cond.dnd5e.restrainedDesc': 'Bewegung wird 0. Angriffe haben Nachteil. Angriffe dagegen haben Vorteil. Nachteil bei Ges.-Rettungswürfen.',
            'cond.dnd5e.stunned': 'Betäubt',
            'cond.dnd5e.stunnedDesc': 'Handlungsunfähig; kann sich nicht bewegen; kann nur stockend sprechen. Scheitert bei St.- und Ges.-Rettungswürfen. Angriffe dagegen haben Vorteil.',
            'cond.dnd5e.unconscious': 'Bewusstlos',
            'cond.dnd5e.unconsciousDesc': 'Handlungsunfähig, liegend, bewusstlos. Lässt gehaltene Gegenstände fallen. Scheitert bei St.- und Ges.-Rettungswürfen. Angriffe dagegen haben Vorteil; Nahkampf trifft kritisch.',
            'cond.pf2e.blinded': 'Geblendet',
            'cond.pf2e.blindedDesc': 'Kann nicht sehen. Jedes Gelände ist schwieriges Gelände. Kritisches Versagen bei Wahrnehmungsproben, die Sicht erfordern.',
            'cond.pf2e.clumsy': 'Ungeschickt',
            'cond.pf2e.clumsyDesc': 'Malus auf Ges.-basierte Proben und WGs, einschließlich RK und Reflex-Rettungswürfe.',
            'cond.pf2e.concealed': 'Verdeckt',
            'cond.pf2e.concealedDesc': 'In Nebel oder Dunkelheit. Kreaturen müssen einen WG-5-Flachtest bestehen, um anzugreifen.',
            'cond.pf2e.confused': 'Verwirrt',
            'cond.pf2e.confusedDesc': 'Kann nicht normal handeln. Greift zufällig an. Ungedeckt. Kann nicht abwarten, bereitstehen oder Reaktionen nutzen.',
            'cond.pf2e.controlled': 'Kontrolliert',
            'cond.pf2e.controlledDesc': 'Jemand anderes wählt die Aktionen. Erholung durch einen Willenswurf möglich.',
            'cond.pf2e.dazzled': 'Geblendet (schwach)',
            'cond.pf2e.dazzledDesc': 'Alles ist verdeckt. Lichtabhängige Fähigkeiten können nicht effektiv genutzt werden.',
            'cond.pf2e.deafened': 'Taub',
            'cond.pf2e.deafenedDesc': 'Kann nicht hören. Scheitert automatisch bei Wahrnehmungsproben, die Hören erfordern. WG-5-Flachtest bei akustischen Aktionen.',
            'cond.pf2e.dying': 'Sterbend',
            'cond.pf2e.dyingDesc': 'Bewusstlos, nahe dem Tod. Erholungswürfe erforderlich. Sterbend 4 bedeutet Tod.',
            'cond.pf2e.fascinated': 'Fasziniert',
            'cond.pf2e.fascinatedDesc': 'Kann keine feindseligen Aktionen ausführen. Malus auf Wahrnehmung und Fertigkeitsproben außer beim Faszinationsobjekt.',
            'cond.pf2e.fatigued': 'Erschöpft',
            'cond.pf2e.fatiguedDesc': 'Malus auf RK und Rettungswürfe. Keine Erkundungsaktivitäten beim Reisen möglich.',
            'cond.pf2e.fleeing': 'Fliehend',
            'cond.pf2e.fleeingDesc': 'Muss Aktionen verwenden, um sich so schnell wie möglich von der Angstquelle zu entfernen.',
            'cond.pf2e.grabbed': 'Gepackt',
            'cond.pf2e.grabbedDesc': 'Immobilisiert und ungedeckt. Manipulationsaktionen außer zum Befreien nicht möglich.',
            'cond.pf2e.hidden': 'Versteckt',
            'cond.pf2e.hiddenDesc': 'Präsenz ist bekannt, genaue Position nicht. WG-11-Flachtest zum Angreifen.',
            'cond.pf2e.offguard': 'Ungedeckt',
            'cond.pf2e.offguardDesc': 'Malus auf RK. Kann durch Flankieren oder andere Zustände verursacht werden.',
            'cond.pf2e.immobilized': 'Immobilisiert',
