            'weapons.trait.dnd5e.twoHanded': 'Zweihändig',
            'weapons.trait.dnd5e.versatile': 'Vielseitig',
            'weapons.trait.dnd5e.ammunitionDesc': 'Eine Waffe mit der Munitionseigenschaft kann nur für Fernkampfangriffe verwendet werden, wenn Munition vorhanden ist. Bei jedem Angriff wird ein Stück Munition verbraucht. Am Ende des Kampfes kann die Hälfte der verbrauchten Munition durch einminütiges Suchen auf dem Schlachtfeld geborgen werden. Wird sie für einen Nahkampfangriff genutzt, gilt sie als improvisierte Waffe.',
            'weapons.trait.dnd5e.finesseDesc': 'Bei Angriffen mit einer Finesse-Waffe kann entweder der Stärke- oder der Geschicklichkeitsmodifikator für Angriffs- und Schadenswürfe verwendet werden. Für beide Würfe muss derselbe Modifikator gewählt werden.',
            'weapons.trait.dnd5e.heavyDesc': 'Kleine Kreaturen haben Nachteil bei Angriffswürfen mit schweren Waffen. Größe und Gewicht machen sie für kleine Kreaturen schwer handhabbar.',
            'weapons.trait.dnd5e.lightDesc': 'Eine leichte Waffe ist klein und leicht zu handhaben, ideal für den Kampf mit zwei Waffen.',
            'weapons.trait.dnd5e.loadingDesc': 'Aufgrund der Nachladezeit kann pro Aktion, Bonusaktion oder Reaktion nur ein Stück Munition abgefeuert werden, unabhängig von der Anzahl möglicher Angriffe.',
            'weapons.trait.dnd5e.reachDesc': 'Diese Waffe verlängert die Reichweite beim Angriff um 5 Fuß, auch für Gelegenheitsangriffe.',
            'weapons.trait.dnd5e.specialDesc': 'Eine Waffe mit der Eigenschaft Besonders hat ungewöhnliche Regeln, die in ihrer Beschreibung erläutert werden.',
            'weapons.trait.dnd5e.thrownDesc': 'Eine Waffe mit der Wurfeigenschaft kann geworfen werden, um einen Fernkampfangriff zu machen. Bei Nahkampfwaffen wird derselbe Modifikator wie für Nahkampfangriffe verwendet.',
            'weapons.trait.dnd5e.twoHandedDesc': 'Diese Waffe erfordert beim Angriff zwei Hände.',
            'weapons.trait.dnd5e.versatileDesc': 'Diese Waffe kann ein- oder beidhändig geführt werden. Der Wert in Klammern gibt den Schaden bei beidhändigem Nahkampf an.',

            // PF2e traits
            'weapons.trait.pf2e.agile': 'Wendig',
