            'weapons.trait.dnd5e.twoHanded': 'A Due Mani',
            'weapons.trait.dnd5e.versatile': 'Versatile',
            'weapons.trait.dnd5e.ammunitionDesc': 'Puoi usare un\'arma con la proprietà Munizioni per fare un attacco a distanza solo se hai munizioni da scagliare. Ogni volta che attacchi con quest\'arma, consumi un proiettile. Estrarre le munizioni da una faretra o contenitore fa parte dell\'attacco (serve una mano libera per caricare un\'arma a una mano). Alla fine del combattimento, puoi recuperare metà delle munizioni spese cercando il campo di battaglia per un minuto. Se usi quest\'arma per un attacco corpo a corpo, è considerata un\'arma improvvisata. Una fionda deve essere carica per infliggere danni.',
            'weapons.trait.dnd5e.finesseDesc': 'Quando attacchi con un\'arma con destrezza, puoi scegliere di usare il modificatore di Forza o Destrezza per i tiri per colpire e per i danni. Devi usare lo stesso modificatore per entrambi i tiri.',
            'weapons.trait.dnd5e.heavyDesc': 'Le creature Piccole hanno svantaggio ai tiri per colpire con armi pesanti. Le dimensioni e la mole di un\'arma pesante la rendono troppo grande per essere usata efficacemente da una creatura Piccola.',
            'weapons.trait.dnd5e.lightDesc': 'Un\'arma leggera è piccola e facile da maneggiare, ideale per il combattimento con due armi.',
            'weapons.trait.dnd5e.loadingDesc': 'A causa del tempo necessario per caricare quest\'arma, puoi sparare solo un proiettile per azione, azione bonus o reazione, indipendentemente dal numero di attacchi che potresti normalmente effettuare.',
            'weapons.trait.dnd5e.reachDesc': 'Quest\'arma aggiunge 1,5 metri alla tua portata quando attacchi con essa, anche per gli attacchi di opportunità.',
            'weapons.trait.dnd5e.specialDesc': 'Un\'arma con la proprietà Speciale ha regole insolite che disciplinano il suo utilizzo, descritte nella scheda dell\'arma.',
            'weapons.trait.dnd5e.thrownDesc': 'Se un\'arma ha la proprietà Da Lancio, puoi lanciarla per fare un attacco a distanza. Se è un\'arma da corpo a corpo, usi lo stesso modificatore di caratteristica che useresti per un attacco in mischia. Ad esempio, se lanci un\'ascia da mano usi Forza; se lanci un pugnale puoi usare Forza o Destrezza.',
            'weapons.trait.dnd5e.twoHandedDesc': 'Quest\'arma richiede due mani quando la impugni per attaccare.',
            'weapons.trait.dnd5e.versatileDesc': 'Quest\'arma può essere usata con una o due mani. Un valore di danno tra parentesi indica il danno quando viene usata con due mani per un attacco in mischia.',

