            'weapons.trait.pf2e.deadly': 'Letale',
            'weapons.trait.pf2e.deadlyDesc': 'Con un colpo critico, quest\'arma aggiunge un dado aggiuntivo della dimensione indicata ai danni. Inserisci la dimensione del dado (es. d8).',
            'weapons.trait.pf2e.fatal': 'Fatale',
            'weapons.trait.pf2e.fatalDesc': 'Con un colpo critico, il dado danno dell\'arma diventa della dimensione indicata e aggiungi 1 dado extra. Inserisci la dimensione del dado (es. d12).',
            'weapons.trait.pf2e.finesse': 'Destrezza',
            'weapons.trait.pf2e.finesseDesc': 'Puoi usare il modificatore di Destrezza invece di quello di Forza per i tiri per colpire con quest\'arma da corpo a corpo.',
