            'weapons.trait.dnd5e.twoHanded': 'Duas Mãos',
            'weapons.trait.dnd5e.versatile': 'Versátil',
            'weapons.trait.dnd5e.ammunitionDesc': 'Você só pode usar uma arma com a propriedade munição para fazer um ataque à distância se tiver munição para disparar. Cada vez que atacar com a arma, gasta uma unidade de munição. Sacar a munição de uma aljava, estojo ou outro recipiente faz parte do ataque (você precisa de uma mão livre para carregar uma arma de uma mão). Ao final da batalha, pode recuperar metade da munição gasta ao tomar um minuto para vasculhar o campo de batalha. Se usar a arma para fazer um ataque corpo a corpo, ela é tratada como improvisada. Uma funda precisa estar carregada para causar qualquer dano dessa forma.',
            'weapons.trait.dnd5e.finesseDesc': 'Ao fazer um ataque com uma arma de finesse, você usa sua escolha entre o modificador de Força ou Destreza para as rolagens de ataque e dano. Deve usar o mesmo modificador para ambas as rolagens.',
            'weapons.trait.dnd5e.heavyDesc': 'Criaturas Pequenas têm desvantagem em rolagens de ataque com armas pesadas. O tamanho e volume de uma arma pesada a tornam grande demais para ser usada com eficiência por uma criatura Pequena.',
            'weapons.trait.dnd5e.lightDesc': 'Uma arma leve é pequena e fácil de manusear, sendo ideal para usar quando se luta com duas armas.',
            'weapons.trait.dnd5e.loadingDesc': 'Por causa do tempo necessário para carregar esta arma, você só pode disparar uma unidade de munição dela quando usa uma ação, ação bônus ou reação para disparar, independentemente do número de ataques que normalmente pode fazer.',
            'weapons.trait.dnd5e.reachDesc': 'Esta arma adiciona 1,5 metro ao seu alcance quando você ataca com ela, bem como ao determinar seu alcance para ataques de oportunidade.',
            'weapons.trait.dnd5e.specialDesc': 'Uma arma com a propriedade especial tem regras incomuns que regem seu uso, explicadas na descrição da arma.',
            'weapons.trait.dnd5e.thrownDesc': 'Se uma arma tiver a propriedade arremessável, você pode arremessá-la para fazer um ataque à distância. Se for uma arma corpo a corpo, use o mesmo modificador de atributo para a rolagem de ataque e de dano que usaria para um ataque corpo a corpo com ela. Por exemplo, ao arremessar um machado de mão, use Força, mas ao arremessar uma adaga, pode usar Força ou Destreza, pois a adaga tem a propriedade finesse.',
            'weapons.trait.dnd5e.twoHandedDesc': 'Esta arma requer duas mãos quando você ataca com ela.',
            'weapons.trait.dnd5e.versatileDesc': 'Esta arma pode ser usada com uma ou duas mãos. Um valor de dano entre parênteses aparece com a propriedade — o dano ao usar com duas mãos para fazer um ataque corpo a corpo.',

            // PF2e traits
            'weapons.trait.pf2e.agile': 'Ágil',
            'weapons.trait.pf2e.agileDesc': 'A penalidade de ataque múltiplo que você sofre com esta arma no segundo ataque é –4 em vez de –5, e –8 em vez de –10 no terceiro e ataques subsequentes no turno.',
            'weapons.trait.pf2e.deadly': 'Mortal',
            'weapons.trait.pf2e.deadlyDesc': 'Em um acerto crítico, esta arma adiciona um dado extra do tamanho indicado ao dano. Informe o tamanho do dado (ex.: d8).',
            'weapons.trait.pf2e.fatal': 'Fatal',
            'weapons.trait.pf2e.fatalDesc': 'Em um acerto crítico, o dado de dano da arma muda para o tamanho indicado e você adiciona 1 dado extra. Informe o tamanho do dado (ex.: d12).',
            'weapons.trait.pf2e.finesse': 'Finesse',
            'weapons.trait.pf2e.finesseDesc': 'Você pode usar seu modificador de Destreza em vez do de Força nas rolagens de ataque com esta arma corpo a corpo.',
            'weapons.trait.pf2e.forceful': 'Poderosa',
            'weapons.trait.pf2e.forcefulDesc': 'Esta arma fica mais poderosa a cada ataque que você faz contra o mesmo alvo. O segundo ataque causa 1 de dano extra e cada ataque subsequente causa 2 de dano extra.',
            'weapons.trait.pf2e.propulsive': 'Propulsiva',
            'weapons.trait.pf2e.propulsiveDesc': 'Você adiciona metade do seu modificador de Força (se positivo) às rolagens de dano com esta arma à distância.',
            'weapons.trait.pf2e.reach': 'Alcance',
            'weapons.trait.pf2e.reachDesc': 'Esta arma pode ser usada para atacar criaturas a até 3 metros de distância em vez de apenas criaturas adjacentes.',
            'weapons.trait.pf2e.sweep': 'Varredura',
            'weapons.trait.pf2e.sweepDesc': 'Esta arma faz movimentos amplos e varridos, concedendo um bônus de circunstância +1 à sua rolagem de ataque se você já tentou atacar um alvo diferente neste turno.',
            'weapons.trait.pf2e.thrown': 'Arremessável',
            'weapons.trait.pf2e.thrownDesc': 'Você pode arremessar esta arma como um ataque à distância. Informe o incremento de alcance (ex.: 6 m).',
            'weapons.trait.pf2e.twoHand': 'Duas Mãos',
            'weapons.trait.pf2e.twoHandDesc': 'Esta arma pode ser empunhada com duas mãos para aumentar seu dano. Informe o tamanho do dado para duas mãos (ex.: d10).',
