            // Conditions — D&D 5e
            'cond.dnd5e.blinded': 'Слепота',
            'cond.dnd5e.blindedDesc': 'Не может видеть. Автоматически проваливает проверки, требующие зрения. Броски атаки с помехой; атаки против — с преимуществом.',
            'cond.dnd5e.charmed': 'Очарован',
            'cond.dnd5e.charmedDesc': 'Не может атаковать очаровавшего. У очаровавшего преимущество на социальные проверки против этого существа.',
            'cond.dnd5e.deafened': 'Глухота',
            'cond.dnd5e.deafenedDesc': 'Не может слышать. Автоматически проваливает проверки, требующие слуха.',
            'cond.dnd5e.exhaustion': 'Истощение',
            'cond.dnd5e.exhaustionDesc': 'Накапливаемые уровни истощения со всё более серьёзными штрафами. 6-й уровень — смерть.',
            'cond.dnd5e.frightened': 'Напуган',
            'cond.dnd5e.frightenedDesc': 'Помеха на проверки и атаки, пока источник страха в поле зрения. Не может по своей воле приближаться к источнику.',
            'cond.dnd5e.grappled': 'Схвачен',
            'cond.dnd5e.grappledDesc': 'Скорость становится 0. Заканчивается, если захватчик недееспособен или отброшен.',
            'cond.dnd5e.incapacitated': 'Недееспособен',
            'cond.dnd5e.incapacitatedDesc': 'Не может совершать действия или реакции.',
            'cond.dnd5e.invisible': 'Невидим',
            'cond.dnd5e.invisibleDesc': 'Не может быть замечен без магии или особых чувств. Броски атаки с преимуществом; атаки против — с помехой.',
            'cond.dnd5e.paralyzed': 'Парализован',
            'cond.dnd5e.paralyzedDesc': 'Недееспособен; не может двигаться или говорить. Автоматически проваливает СИЛ/ЛОВ спасброски. Атаки против — с преимуществом; попадания в ближнем бою критические.',
            'cond.dnd5e.petrified': 'Окаменел',
            'cond.dnd5e.petrifiedDesc': 'Превращён в камень. Недееспособен, не осознаёт окружающего. Сопротивление всем видам урона. Иммунитет к яду и болезням.',
            'cond.dnd5e.poisoned': 'Отравлен',
            'cond.dnd5e.poisonedDesc': 'Помеха на броски атаки и проверки характеристик.',
            'cond.dnd5e.prone': 'Лежит',
            'cond.dnd5e.proneDesc': 'Может только ползти. Помеха на броски атаки. Атаки в ближнем бою против — с преимуществом; дальние — с помехой.',
            'cond.dnd5e.restrained': 'Опутан',
            'cond.dnd5e.restrainedDesc': 'Скорость становится 0. Помеха на броски атаки. Атаки против — с преимуществом. Помеха на спасброски Ловкости.',
            'cond.dnd5e.stunned': 'Ошеломлён',
            'cond.dnd5e.stunnedDesc': 'Недееспособен; не может двигаться; говорит лишь невнятно. Автоматически проваливает СИЛ/ЛОВ спасброски. Атаки против — с преимуществом.',
            'cond.dnd5e.unconscious': 'Без сознания',
            'cond.dnd5e.unconsciousDesc': 'Недееспособен, лежит, не осознаёт окружающего. Роняет предметы. Автоматически проваливает СИЛ/ЛОВ спасброски. Атаки против — с преимуществом; попадания критические.',

            // Conditions — Pathfinder 2e
            'cond.pf2e.blinded': 'Слепота',
            'cond.pf2e.blindedDesc': 'Не может видеть. Вся местность — труднопроходимая. Критический провал проверок Восприятия, требующих зрения.',
            'cond.pf2e.clumsy': 'Неуклюж',
            'cond.pf2e.clumsyDesc': 'Штраф к проверкам и КС на основе Ловкости, включая КД и спасброски Рефлексов.',
            'cond.pf2e.concealed': 'Скрыт',
            'cond.pf2e.concealedDesc': 'В тумане или темноте. Существа должны пройти простую проверку КС 5, чтобы атаковать вас.',
            'cond.pf2e.confused': 'Дезориентирован',
            'cond.pf2e.confusedDesc': 'Не может действовать нормально. Атакует случайных целей. Без прикрытия. Не может откладывать, готовиться или использовать реакции.',
            'cond.pf2e.controlled': 'Подконтролен',
            'cond.pf2e.controlledDesc': 'Кто-то другой выбирает ваши действия. Можно попытаться освободиться спасброском Воли.',
            'cond.pf2e.dazzled': 'Ослеплён Блеском',
            'cond.pf2e.dazzledDesc': 'Всё вокруг скрыто от вас. Не можете эффективно использовать способности, требующие света.',
            'cond.pf2e.deafened': 'Глухота',
            'cond.pf2e.deafenedDesc': 'Не может слышать. Автоматически проваливает проверки Восприятия на слух. Простая проверка КС 5 для слуховых действий.',
            'cond.pf2e.dying': 'Умирает',
            'cond.pf2e.dyingDesc': 'Без сознания, при смерти. Нужно совершать броски восстановления. Умирает-4 означает смерть.',
            'cond.pf2e.fascinated': 'Очарован',
            'cond.pf2e.fascinatedDesc': 'Не может совершать враждебные действия. Штраф к Восприятию и навыкам, кроме связанных с источником очарования.',
            'cond.pf2e.fatigued': 'Истощён',
            'cond.pf2e.fatiguedDesc': 'Штраф к КД и спасброскам. Не может использовать действия исследования во время путешествия.',
            'cond.pf2e.fleeing': 'Бежит',
            'cond.pf2e.fleeingDesc': 'Должен тратить действия на удаление от источника страха самым быстрым способом.',
            'cond.pf2e.grabbed': 'Схвачен',
            'cond.pf2e.grabbedDesc': 'Обездвижен и без прикрытия. Не может совершать манипулятивные действия, кроме попыток вырваться.',
            'cond.pf2e.hidden': 'Скрыт',
